 }
 $o|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $durable $n) -Encoding UTF8
}
function Get-Sha256($p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToUpperInvariant()}
